out={'schema':'marici.benincasa.cosmology-half-twist-diagonal-witness-profiles-summary.v1','primes':[32003,32009],'candidate_count':9,'profiles_prime_stable':True,'closure_count_classes':classes,'single_common_skeleton_falsified':True,'top_K3_interior_shift_class_candidates':[5,6,7,8],'top_K3_interior_common_family_counts':{'IBP':287,'K':165,'q':683},'top_K3_interior_common_closure_size':1135,'top_K3_interior_skeletons_identical_without_shift_normalization':False,'top_K3_interior_shift_normalized_support_hashes':[x['shift_normalized_relation_support_sha256'] for x in a['profiles'][5:9]],'top_K3_interior_shift_normalized_supports_identical':False,'pivot_DAG_shift_template_falsified':True,'source_natural_stratified_homotopy_open':True,'interpretation':'the nine witnesses do not share one skeleton; even candidates 5-8, which share closure and family counts, have distinct relation-support multisets after monomial-exponent normalization, falsifying a pivot-DAG shift template','passed':True};(R/'cosmology_half_twist_diagonal_witness_profiles_summary.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
